 export type PortRange = [number, number];
+
+const MAX_PORT = 65535;
+
+function parsePort(text: string): number {
+  if (!/^\d+$/.test(text)) {
+    throw new Error(`not a port number: "${text}"`);
+  }
+  const port = Number(text);
+  if (port < 1 || port > MAX_PORT) {
+    throw new Error(`port outside 1-65535: "${text}"`);
+  }
+  return port;
+}
+
+function parseItem(item: string): PortRange {
+  const text = item.trim();
+  if (text === "") {
+    throw new Error("empty item in port list");
+  }
+  const bounds = text.split("-");
+  if (bounds.length === 1) {
+    const port = parsePort(text);
+    return [port, port];
+  }
+  if (bounds.length !== 2) {
+    throw new Error(`malformed range: "${text}"`);
+  }
+  const from = parsePort(bounds[0].trim());
+  const to = parsePort(bounds[1].trim());
+  if (to < from) {
+    throw new Error(`range end below start: "${text}"`);
+  }
+  return [from, to];
+}
+
+function mergeRanges(ranges: PortRange[]): PortRange[] {
+  const sorted = [...ranges].sort((a, b) => a[0] - b[0]);
+  const merged: PortRange[] = [];
+  for (const [from, to] of sorted) {
+    const last = merged.at(-1);
+    if (last && from <= last[1] + 1) {
+      last[1] = Math.max(last[1], to);
+    } else {
+      merged.push([from, to]);
+    }
+  }
+  return merged;
+}

